    u.id !== 'KENNY' &&
    Auth &&
    typeof Auth.crozzoStaffRowUsesLegacyPlaintext === 'function' &&
    Auth.crozzoStaffRowUsesLegacyPlaintext(u) &&
    segLogin.bloquearClavePlanoEnLogin
