  if (typeof crozzoCajaSessionMarkLogin === 'function') crozzoCajaSessionMarkLogin();
  try { sessionStorage.removeItem('crozzo_cloud_profile'); } catch (_) {}
  try { sessionStorage.setItem('crozzo_session_user', u.id); } catch (e) { /* ignore */ }
