async function crozzoHpTryContainmentUnlock() {
  const user = document.getElementById('crozzoHpAssistUser')?.value || '';
  const pass = document.getElementById('crozzoHpAssistPass')?.value || '';
  const err = document.getElementById('crozzoHpContainmentErr');
  const showErr = msg => {
    if (err) {
      err.textContent = msg;
      err.hidden = !msg;
    }
  };
  const Auth = window.CrozzoAuthSecurity;
  if (!Auth || typeof Auth.crozzoHoneypotClearLegendLock !== 'function') {
    return showErr('Módulo de seguridad no disponible.');
  }
  if (!user.trim() || !pass.trim()) {
    return showErr('Ingrese usuario de asistencia y clave de liberación.');
  }
  await crozzoHpEnsureLegendUnlockReady();
  const seg = config.get('seguridad') || {};
  const res = await Auth.crozzoHoneypotClearLegendLock(pass.trim(), seg, window, {
    requireSuperAdmin: false,
    assistUser: user,
  });
  if (!res.ok) {
    if (res.error === 'usuario_invalido') {
      return showErr('Usuario de asistencia incorrecto. Use «Asistencia general».');
    }
    if (res.error === 'codigo_invalido') {
      return showErr('Clave de liberación incorrecta. El bloqueo permanece activo.');
    }
    return showErr('No se pudo desactivar el bloqueo.');
  }
  showErr('');
  crozzoHpHideContainment();
  if (typeof crozzoRefreshLoginHoneypotBanner === 'function') crozzoRefreshLoginHoneypotBanner();
  if (typeof showLoginOverlay === 'function') showLoginOverlay();
  if (typeof showToast === 'function') {
    showToast('Bloqueo de seguridad desactivado. Ya puede iniciar sesión con su usuario habitual.', 'success');
  }
}
