function crozzoRefreshLoginHoneypotBanner() {
  const el = document.getElementById('loginHoneypotLock');
  const blocked = document.getElementById('loginHoneypotBlocked');
  const dumpEl = document.getElementById('loginHoneypotDeviceDump');
  const caseRef = document.getElementById('loginHoneypotCaseRef');
  const box = document.getElementById('loginLegendUnlockBox');
  const loginUser = document.getElementById('loginUsername');
  const loginPass = document.getElementById('loginPassword');
  const submitBtn = document.querySelector('#loginForm button[type="submit"]');
  if (!window.CrozzoAuthSecurity) return;
  const seg = config.get('seguridad') || {};
  const hp = seg.honeypot || {};
  const lock = CrozzoAuthSecurity.crozzoHoneypotLockActive(seg);
  const setFormBlocked = on => {
    document.body.classList.toggle('crozzo-login-hp-blocked', on);
    if (loginUser) loginUser.disabled = on;
    if (loginPass) loginPass.disabled = on;
    if (submitBtn) submitBtn.disabled = on;
  };
  // KENNY + PIN soporte siempre puede usar el formulario (aunque haya cuarentena).
  setFormBlocked(false);
  if (lock.locked && lock.legendary) {
    if (el) {
      el.textContent = 'Cuarentena activa — ingrese con KENNY y PIN de soporte para liberar.';
      el.hidden = false;
    }
    if (blocked) blocked.hidden = true;
    if (dumpEl) dumpEl.textContent = '';
    if (caseRef) caseRef.textContent = '';
    if (box) {
      box.hidden = true;
      box.open = false;
    }
    return;
  } else if (lock.locked) {
    if (blocked) blocked.hidden = true;
    if (dumpEl) dumpEl.textContent = '';
    if (caseRef) caseRef.textContent = '';
    if (el) {
      el.textContent = 'Acceso suspendido ' + (lock.minutos || '?') + ' min — KENNY puede ingresar.';
      el.hidden = false;
    }
    if (box) box.open = false;
  } else {
    if (el) {
      el.hidden = true;
      el.textContent = '';
    }
    if (blocked) blocked.hidden = true;
    if (dumpEl) dumpEl.textContent = '';
    if (caseRef) caseRef.textContent = '';
    if (box) {
      box.hidden = true;
      box.open = false;
    }
    if (typeof crozzoHpHideContainment === 'function') crozzoHpHideContainment();
  }
}
