function crozzoHpMapDecoyRol(rol) {
  const r = String(rol || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '_');
  if (r === 'superadmin' || r === 'super_admin') return 'admin';
  if (r === 'gerente' || r === 'director' || r === 'auditor' || r === 'contador' || r === 'facturacion') return 'admin';
  if (r === 'mesero' || r === 'caja' || r === 'admin' || r === 'inventario' || r === 'cocina') return r;
  return 'caja';
}
