    crozzoHpScheduleIntrusionAlerts(liveMs, decoy, trip, { shortDemo: shortDemo });
    await new Promise(resolve => {
      window.__crozzoHpResolveLivePhase = resolve;
      window.__crozzoHpLiveMainTimer = setTimeout(resolve, liveMs);
      window.__crozzoHpLiveEndEarly = delayMs => {
        if (window.__crozzoHpLiveMainTimer) clearTimeout(window.__crozzoHpLiveMainTimer);
        window.__crozzoHpLiveMainTimer = setTimeout(resolve, Math.max(2000, delayMs || 10000));
      };
    });
    window.__crozzoHpResolveLivePhase = null;
    window.__crozzoHpLiveEndEarly = null;
    if (window.__crozzoHpLiveMainTimer) {
      clearTimeout(window.__crozzoHpLiveMainTimer);
      window.__crozzoHpLiveMainTimer = null;
    }
    crozzoHpClearIntrusionAlerts();
    if (typeof crozzoHpScrubDbChaff === 'function') crozzoHpScrubDbChaff();
    crozzoHoneypotLiveEnd();
    const breachShort = shortDemo && adminPreview;
    await crozzoHpRunBreachPhase(trip, decoy, ctx, Sim, believable, adminPreview, skipFinalize || breachShort);
    if (!skipFinalize && !breachShort) {
      const Auth = window.CrozzoAuthSecurity;
      const seg = config.get('seguridad') || {};
      if (Auth && typeof Auth.ensureHoneypotLegendUnlock === 'function') {
        await Auth.ensureHoneypotLegendUnlock(seg, window);
      }
      if (Auth && typeof Auth.crozzoHoneypotFinalizeTrip === 'function') {
        Auth.crozzoHoneypotFinalizeTrip(seg, trip, window);
      }
      try {
        if (typeof crozzoHpShowContainmentAsync === 'function') {
          await crozzoHpShowContainmentAsync();
        } else if (typeof crozzoHpShowContainment === 'function') {
          crozzoHpShowContainment();
        }
      } catch (_) {}
    }
    if (ov) {
      ov.setAttribute('hidden', '');
      ov.classList.remove('crozzo-honeypot--real', 'crozzo-honeypot--admin');
    }
    if (adminBadge) adminBadge.setAttribute('hidden', '');
    document.body.classList.remove('crozzo-honeypot-active', 'crozzo-honeypot-real-app', 'crozzo-honeypot-live');
    if (!document.body.classList.contains('crozzo-hp-containment-active')) {
      document.body.style.overflow = '';
    }
    try {
      var emShellHp = document.getElementById('crozzo-emergency-shell');
      if (emShellHp) emShellHp.removeAttribute('data-hp-hidden');
    } catch (_) {}
    if (bar) bar.style.width = '0%';
    if (status) status.textContent = '';
