    sandboxInteractiveMinMinutes: parseInt(document.getElementById('cfgHpLiveMin')?.value, 10) || 1,
    sandboxInteractiveMaxMinutes: parseInt(document.getElementById('cfgHpLiveMax')?.value, 10) || 5,
    breachSeconds: parseInt(document.getElementById('cfgHpBreachSec')?.value, 10) || 14,
