  if (String(candidate.id || '').toUpperCase() === 'KENNY') return candidate;
  const Auth = window.CrozzoAuthSecurity;
  if (Auth && typeof Auth.hasHashFields === 'function' && Auth.hasHashFields(candidate)) return candidate;
