  if (!cmdCfg.autoPrint) return false;
  const area =
    areaCfg || (getComandasConfig().areas || []).find((a) => a.id === c.areaId);
  const prn = crozzoComandaAreaEffectivePrinter(area);
  if (!prn) return false;
  opts = opts || {};
  if (opts.fromSend) return true;
