function initCajero() {
  if (document.body) document.body.classList.add('crozzo-page-rest-pos');
  if (typeof crozzoRetailToggleCliente === 'function') crozzoRetailToggleCliente(false);
  crozzoRememberSalesPage('cajero');
  if (!window.__crozzoCuentaCobroMenuDocBound) {
    window.__crozzoCuentaCobroMenuDocBound = true;
    document.addEventListener('click', function () {
      if (typeof crozzoCloseCuentaCobroMenu === 'function') crozzoCloseCuentaCobroMenu();
    });
  }
  const searchInput = document.getElementById('searchProduct');
  if (searchInput && !searchInput._crozzoSearchBound) {
    searchInput._crozzoSearchBound = true;
    let searchDebounceT = null;
    searchInput.addEventListener('input', (e) => {
      const v = e.target.value;
      if (searchDebounceT) clearTimeout(searchDebounceT);
      searchDebounceT = setTimeout(() => {
        productSearchTerm = v;
        crozzoCajeroRefreshProductsGrid();
      }, 150);
    });
  }
  const nitInput = document.getElementById('nitCliente');
  if (nitInput) {
    nitInput.addEventListener('input', (e) => {
      const val = (e.target.value || '').trim();
      const status = document.getElementById('nitStatus');
      if (!val) {
        if (status) status.innerHTML = '';
        nitInput.classList.remove('valid', 'invalid');
        return;
      }
      const result = validarNIT(val, { relajado: true });
      if (!status) return;
      if (result.valido) {
        if (result.modo === 'nit_dian') {
          status.innerHTML = '<span class="form-success">✓ NIT-DV verificado (DIAN)</span>';
          nitInput.title = '';
        } else if (result.modo === 'cedula_o_documento') {
          status.innerHTML = '<span class="form-success">✓ Documento / referencia</span>';
          nitInput.title = 'Cédula u otro ID numérico. Para NIT de empresa con DV verificado usa formato 900123456-1.';
        } else if (result.modo === 'dv_no_verificado') {
          status.innerHTML = '<span class="form-warning">⚠ DV no verificado (referencia)</span>';
          nitInput.title = result.advertencia || '';
        } else {
          status.innerHTML = '<span class="form-success">✓ Referencia</span>';
          nitInput.title = '';
        }
        nitInput.classList.add('valid');
        nitInput.classList.remove('invalid');
      } else {
        status.innerHTML = '<span class="form-error">✗ ' + escHtml(crozzoUserFacingError(result.error)) + '</span>';
        nitInput.classList.add('invalid');
        nitInput.classList.remove('valid');
        nitInput.title = '';
      }
    });
  }
  const mesaSearchEl = document.getElementById('cajaMesaSearch');
  if (mesaSearchEl && !mesaSearchEl._crozzoMesaSearchBound) {
    mesaSearchEl._crozzoMesaSearchBound = true;
    let mesaDebounceT = null;
    mesaSearchEl.addEventListener('input', (e) => {
      cajaMesaSearch = e.target.value;
      if (mesaDebounceT) clearTimeout(mesaDebounceT);
      mesaDebounceT = setTimeout(() => {
        if (typeof crozzoCajeroRefreshSlotPicker === 'function' && crozzoCajeroRefreshSlotPicker()) return;
        renderPage('cajero');
      }, 120);
    });
  }
  const llevarSearchEl = document.getElementById('cajaLlevarSearch');
  if (llevarSearchEl && !llevarSearchEl._crozzoLlevarSearchBound) {
    llevarSearchEl._crozzoLlevarSearchBound = true;
    let llevarDebounceT = null;
    llevarSearchEl.addEventListener('input', (e) => {
      cajaLlevarSearch = e.target.value;
      if (llevarDebounceT) clearTimeout(llevarDebounceT);
      llevarDebounceT = setTimeout(() => {
        if (typeof crozzoCajeroRefreshSlotPicker === 'function' && crozzoCajeroRefreshSlotPicker()) return;
        renderPage('cajero');
      }, 120);
    });
  }
  // Al abrir Caja/Mesas, pinta de inmediato lo ya comandado
  try {
    renderCart();
  } catch (cartErr) {
    console.warn('[cajero] renderCart', cartErr);
  }
  if (typeof crozzoHydrateClienteSlotToForm === 'function') crozzoHydrateClienteSlotToForm();
  if (typeof crozzoCrmLiteBindCartUi === 'function') crozzoCrmLiteBindCartUi();
  try {
    var root = document.getElementById('mainContent');
    if (typeof lucide !== 'undefined' && lucide.createIcons && root) lucide.createIcons({ root: root });
  } catch (_) {}
  if (typeof crozzoUpdatePrintQueueBar === 'function') crozzoUpdatePrintQueueBar();
}
function initTablets() {
  const searchInput = document.getElementById('tabletSearchProduct');
  if (searchInput && !searchInput._crozzoTabSearchBound) {
    searchInput._crozzoTabSearchBound = true;
    let tabSearchDebounceT = null;
    searchInput.addEventListener('input', (e) => {
      const term = e.target.value.toLowerCase();
      if (tabSearchDebounceT) clearTimeout(tabSearchDebounceT);
      tabSearchDebounceT = setTimeout(() => {
        if (typeof currentPage !== 'undefined' && currentPage !== 'tablets') return;
        document.querySelectorAll('#tabletProducts .product-card').forEach((card) => {
          const name = card.getAttribute('data-name');
          card.style.display = name.includes(term) ? '' : 'none';
        });
      }, 150);
    });
  }
  const targetSearchEl = document.getElementById('tabletSearchTarget');
  if (targetSearchEl) {
    targetSearchEl.addEventListener('input', (e) => setTabletTargetSearch(e.target.value));
  }
  if (document.getElementById('crozzoCrmWrap')) {
    if (typeof crozzoHydrateClienteSlotToForm === 'function') crozzoHydrateClienteSlotToForm();
    crozzoCrmLiteBindCartUi();
    if (typeof CrozzoCrmRegistroQr !== 'undefined' && CrozzoCrmRegistroQr.mountTabletCrmExtras) {
      CrozzoCrmRegistroQr.mountTabletCrmExtras();
    }
    if (typeof CrozzoAdquirienteLookup !== 'undefined') {
      if (typeof CrozzoAdquirienteLookup.bindForm === 'function') CrozzoAdquirienteLookup.bindForm('crm_new');
      if (typeof CrozzoAdquirienteLookup.bindAllVisible === 'function') CrozzoAdquirienteLookup.bindAllVisible();
    }
  }
  try {
    if (tabletOrderOpen) crozzoStartOrderSessionLockHeartbeat();
  } catch (_) {}
  try {
    if (typeof crozzoBindTabletCartDrawerUi === 'function') crozzoBindTabletCartDrawerUi();
  } catch (_) {}
}
function crozzoCajaClientesRowsHtml() {
  const list = typeof crozzoCrmGetClients === 'function' ? crozzoCrmGetClients() : [];
  const needle = normalizeText(window.__crozzoClienteDirSearch || '');
  const filtered = list.filter((c) => {
    const hay = normalizeText(
      [c.nit, c.nombre, c.telefono, c.email || '', (crozzoCrmClientEmailsArray(c) || []).join(' '), c.ciudad || '', c.direccion || ''].join(' ')
    );
    return !needle || hay.includes(needle);
  });
  return filtered
    .slice()
    .sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es'))
    .map((c) => {
      const id = String(c.id || '').replace(/"/g, '&quot;');
      return `
      <tr>
        <td style="font-size:0.82rem;">${crozzoCrmEscAttr(c.nit || '—')}</td>
        <td style="font-size:0.82rem;"><strong>${crozzoCrmEscAttr(c.nombre || '')}</strong></td>
        <td style="font-size:0.82rem;">${crozzoCrmEscAttr(c.telefono || '—')}</td>
        <td style="font-size:0.78rem;">${crozzoCrmEscAttr(crozzoCrmClientEmailsShort(c))}</td>
        <td style="font-size:0.78rem;">${crozzoCrmEscAttr(c.ciudad || '—')}</td>
        <td style="text-align:right;white-space:nowrap;">
          <button type="button" class="btn btn-outline" style="padding:4px 8px;font-size:0.75rem;" onclick="crozzoCajaClientesOpenEdit('${id}')">Editar</button>
          <button type="button" class="btn btn-outline" style="padding:4px 8px;font-size:0.75rem;margin-left:4px;color:var(--danger);border-color:color-mix(in srgb, var(--danger) 45%, var(--border));" onclick="crozzoCrmDeleteClient('${id}')">Eliminar</button>
        </td>
      </tr>`;
    })
    .join('');
}
function crozzoCajaClientesRefreshTable() {
  const tbody = document.getElementById('crozzoClientesDirTbody');
  if (!tbody) return;
  const rows = crozzoCajaClientesRowsHtml();
  tbody.innerHTML =
    rows || '<tr><td colspan="6" style="padding:20px;text-align:center;color:var(--text-muted);">Sin coincidencias. Borre el filtro o cree un cliente nuevo.</td></tr>';
}
