function crozzoCrmValidateCreditSale(total, metodoPago) {
  if (metodoPago === 'cartera_pendiente') {
    const c0 = crozzoCrmResolveClientFromForm();
    if (!c0) {
      return { ok: false, msg: 'Para «Cobrar después» indique un cliente (NIT en CRM o regístrelo).' };
    }
    return { ok: true, client: c0 };
  }
  if (metodoPago !== 'credito') return { ok: true };
  const c = crozzoCrmResolveClientFromForm();
  if (!c) {
    return { ok: false, msg: 'Para cartera/crédito selecciona un cliente CRM o indica un NIT ya registrado en CRM con cupo.' };
  }
  const lim = Number(c.limiteCredito || 0);
  if (lim <= 0) return { ok: false, msg: 'Configura el cupo de crédito del cliente (CRM → Cupo crédito).' };
  const used = Number(c.creditoUsado || 0);
  const t = Number(total || 0);
  if (used + t > lim + 0.0001) {
    return {
      ok: false,
      msg: `Cupo insuficiente: disponible $${(lim - used).toLocaleString('es-CO')}, venta $${t.toLocaleString('es-CO')}.`,
    };
  }
  return { ok: true, client: c };
}
function crozzoCrmUpdateCreditBadgeEl(c) {
  const badge = document.getElementById('crozzoCrmCreditBadge');
  if (!badge) return;
  const lim = Number(c.limiteCredito || 0);
  const used = Number(c.creditoUsado || 0);
  if (lim <= 0) {
    badge.className = 'crozzo-crm-badge ok';
    badge.textContent = 'Sin cupo';
    return;
  }
  const avail = lim - used;
  if (avail <= 0) {
    badge.className = 'crozzo-crm-badge crit';
    badge.textContent = '🚫 Cupo agotado';
  } else if (avail < lim * 0.2) {
    badge.className = 'crozzo-crm-badge warn';
    badge.textContent = `⚠️ Disp. $${avail.toLocaleString('es-CO')}`;
  } else {
    badge.className = 'crozzo-crm-badge ok';
    badge.textContent = `✅ Disp. $${avail.toLocaleString('es-CO')}`;
  }
}
