async function saveLANConfig() {
  const L = readLANSavePayload();
  let locationIdFinal = (L.locationId || '').trim();
  if (L.lanSyncEnabled) {
    if (L.role === 'B' && !isValidLanIPv4(L.centralIp)) {
      showToast('Rol B (cliente): indica una IP válida del servidor principal.', 'warning');
      document.getElementById('mdCentralIp')?.focus();
      return;
    }
    if (L.role === 'B' && !L.centralIp.trim()) {
      showToast('Rol B: la IP del servidor es obligatoria.', 'warning');
      document.getElementById('mdCentralIp')?.focus();
      return;
    }
    if (window.CrozzoNetworkGuard) {
      if (!locationIdFinal) {
        locationIdFinal = await CrozzoNetworkGuard.ensureLocationIdForPayload(L);
      }
      const locInp = document.getElementById('mdLocationIdDisplay');
      if (locInp) locInp.value = locationIdFinal;
      if (L.role === 'A') {
        const res = await CrozzoNetworkGuard.checkActiveServersOnNetwork({
          locationId: locationIdFinal,
          deviceId: ensureCrozzoDeviceId(),
          port: L.port
        });
        if (res.peers.length > 0 && !CrozzoNetworkGuard.isForceDualServerA()) {
          const choice = await crozzoOpenServerConflictModal(res.peers);
          if (choice === 'cancel') {
            showToast('Activación cancelada. La configuración anterior no se cambió.', 'info');
            return;
          }
          if (choice === 'to_b') {
            setMultiRoleUI('B');
            CrozzoNetworkGuard.setIsActiveServer(false);
            try {
              localStorage.setItem('crozzo_server_conflict_banner', 'Otro Servidor A está en esta red: se cambió a Tablet B. Indica la IP del central y guarda de nuevo.');
            } catch (e) { /* ignore */ }
            if (typeof crozzoWizardTierLogLine === 'function') {
              crozzoWizardTierLogLine('⚠️ Conflicto: degradado a modo Tablet B (había otro servidor A).');
            }
            updateCrozzoServerConflictBadge();
            showToast('Rol cambiado a Tablet (B). Indica la IP del servidor existente y pulsa Guardar.', 'warning');
            return;
          }
          if (choice === 'force_a') {
            CrozzoNetworkGuard.setForceDualServerA(true);
            try {
              localStorage.setItem('crozzo_server_conflict_banner', 'Advertencia: dos Servidores A forzados — riesgo de duplicados.');
            } catch (e2) { /* ignore */ }
            if (typeof crozzoWizardTierLogLine === 'function') {
              crozzoWizardTierLogLine('⚠️ Forzar Servidor A pese a conflicto (split-brain posible).');
            }
            showToast('Servidor A forzado: revisa la red cuanto antes.', 'warning');
          }
        } else {
          try {
            localStorage.removeItem('crozzo_server_conflict_banner');
          } catch (e3) { /* ignore */ }
          CrozzoNetworkGuard.setForceDualServerA(false);
          if (typeof crozzoWizardTierLogLine === 'function') {
            crozzoWizardTierLogLine('✅ Sin otro Servidor A detectado para esta ubicación (HTTP/Realtime).');
          }
        }
      }
      if (L.role === 'B' && L.centralIp) {
        const st = await CrozzoNetworkGuard.probeCentralStatus(L.centralIp, L.port);
        if (st && st.location_id && locationIdFinal && st.location_id !== locationIdFinal) {
          showToast('Ese servidor pertenece a otra ubicación (location distinto). Revisa Wi‑Fi o la nota de red.', 'error');
          return;
        }
      }
    }
  }
  const Lsave = { ...L, locationId: locationIdFinal };
  try {
    if (!L.lanSyncEnabled) {
      localStorage.removeItem(CROZZO_LAN_CONFIG_KEY);
      if (window.CrozzoNetworkGuard) {
        CrozzoNetworkGuard.setIsActiveServer(false);
        CrozzoNetworkGuard.stopHeartbeat();
      }
    } else {
      localStorage.setItem(CROZZO_LAN_CONFIG_KEY, JSON.stringify({ version: 2, ...Lsave, savedAt: Date.now() }));
    }
  } catch (e) {
    showToast('No se pudo guardar la configuración LAN', 'error');
    return;
  }
  const merged = getMultiDeviceConfig();
  const saved = persistMultiDeviceConfig(L.lanSyncEnabled ? merged : { ...merged, allowLan: false });
  if (multiSyncRouter) multiSyncRouter.applyConfig(saved);
  else {
    multiSyncRouter = new MultiDeviceSyncRouter(saved);
    bindMultiStatus();
  }
  if (window.CrozzoNetworkGuard) {
    if (L.lanSyncEnabled && L.role === 'A') {
      CrozzoNetworkGuard.setIsActiveServer(true);
      CrozzoNetworkGuard.afterMainInit();
    } else {
      CrozzoNetworkGuard.setIsActiveServer(false);
      CrozzoNetworkGuard.stopHeartbeat();
    }
  }
  try {
    await multiSyncRouter.runHealthChecks();
  } catch (e) {
    /* ignore */
  }
  updateMdConnectionStatus();
  updateCrozzoServerConflictBadge();
  if (window.CrozzoLanSyncBridge) {
    if (L.lanSyncEnabled && L.role === 'A') {
      try {
        await window.CrozzoLanSyncBridge.syncFromConfig();
      } catch (_) {}
    } else if (typeof window.CrozzoLanSyncBridge.stopServer === 'function') {
      try {
        await window.CrozzoLanSyncBridge.stopServer();
      } catch (_) {}
    }
  }
  config.addAudit('multidispositivo_lan', `LAN sync=${L.lanSyncEnabled} rol=${L.role} loc=${locationIdFinal || '—'}`);
  try {
    if (typeof crozzoStartPosRuntimeCloudSync === 'function') crozzoStartPosRuntimeCloudSync();
  } catch (_) {}
  if (typeof crozzoRunFullReconnectSync === 'function') {
    crozzoRunFullReconnectSync({ force: true, source: 'save_lan' }).catch(() => {});
  }
  showToast(L.lanSyncEnabled ? '✅ Configuración LAN guardada.' : '✅ LAN desactivada. Solo datos locales para red.', 'success');
}
function updateCrozzoAutoConfigBadge(mode) {
  const el = document.getElementById('crozzoAutoConfigBadge');
  if (!el) return;
  el.classList.remove('is-ready', 'is-busy', 'is-error');
  if (mode === 'configuring') {
    el.classList.add('is-busy');
    el.textContent = '🟡 Configurando...';
    el.setAttribute('title', 'Detectando red y aplicando sincronización…');
  } else if (mode === 'error') {
    el.classList.add('is-error');
    el.textContent = '🔴 Error';
    el.setAttribute('title', 'Revisa la configuración o usa el modo avanzado');
  } else {
    el.classList.add('is-ready');
    el.textContent = '✅ Listo';
    el.setAttribute('title', 'Asistente de configuración');
  }
}
