function bindMultiStatus() {
  if (!multiSyncRouter) return;
  if (multiStatusUnsubscribe) { try { multiStatusUnsubscribe(); } catch (e) { /* ignore */ } }
  multiStatusUnsubscribe = multiSyncRouter.on('statusChanged', (st) => updateMultiStatusUI(st));
  updateMultiStatusUI(multiSyncRouter.status);
  multiSyncRouter.on('itemSynced', (item) => {
    if (item && item.target) showToast(`Sincronizado vía ${item.target.toUpperCase()}: ${item.type}`, 'success');
  });
  multiSyncRouter.on('itemFailed', (item) => showToast(`Falló: ${item.type} (${item.uuid?.slice(0, 8) || ''})`, 'error'));
}
function updateMultiStatusUI(st) {
  if (!st) return;
  const cloudCard = document.getElementById('mdPriCloud');
  const lanCard = document.getElementById('mdPriLan');
  const offCard = document.getElementById('mdPriOff');
  const cloudMeta = document.getElementById('mdPriCloudMeta');
  const lanMeta = document.getElementById('mdPriLanMeta');
  const offMeta = document.getElementById('mdPriOffMeta');
  const lastBadge = document.getElementById('mdLastTarget');
  const queueCount = document.getElementById('mdQueueCount');
  if (cloudCard) {
    cloudCard.classList.toggle('is-active', st.cloud === 'online');
    cloudCard.classList.toggle('is-down', st.cloud === 'offline');
  }
  if (lanCard) {
    lanCard.classList.toggle('is-active', st.lan === 'online' && st.cloud !== 'online');
    lanCard.classList.toggle('is-down', st.lan === 'offline');
  }
  if (offCard) {
    const offlineActive = st.cloud !== 'online' && st.lan !== 'online';
    offCard.classList.toggle('is-active', offlineActive);
  }
  if (cloudMeta) cloudMeta.textContent = st.cloud === 'online' ? '☁️ Conectado' : st.cloud === 'offline' ? '⚪ Sin nube' : '⏳ Comprobando…';
  if (lanMeta) lanMeta.textContent = st.lan === 'online' ? '📶 LAN viva' : st.lan === 'offline' ? '⚪ LAN inactiva' : '⏳ Comprobando…';
  if (offMeta) offMeta.textContent = st.cloud === 'online' || st.lan === 'online' ? 'Listo como respaldo' : '💾 Guardando local';
  if (lastBadge) {
    lastBadge.className = 'md-target-badge ' + (st.lastTarget || 'offline');
    const map = { cloud: '☁️ Última: Cloud', lan: '📶 Última: LAN', p2p: '🔗 Última: P2P', offline: '💾 Última: Offline' };
    lastBadge.textContent = map[st.lastTarget] || '— sin envíos —';
  }
  if (queueCount) queueCount.textContent = String(st.pending || 0);
}
function generateBusinessId() {
  const nameInp = document.getElementById('mdBusinessName');
  const inp = document.getElementById('mdBusinessId');
  if (!inp) return;
  const name = (nameInp && nameInp.value || '').trim();
  if (name && typeof window.crozzoLookupBusinessInCloud === 'function') {
    void window.crozzoLookupBusinessInCloud(name).then(function (hit) {
      if (hit && hit.businessId) {
        inp.value = hit.businessId;
        showToast('Negocio en nube: ' + (hit.businessName || name) + ' · ' + hit.businessId, 'success');
        return;
      }
      crozzoGenerateBusinessIdLocal(nameInp, inp, name);
    }).catch(function () {
      crozzoGenerateBusinessIdLocal(nameInp, inp, name);
    });
    return;
  }
  crozzoGenerateBusinessIdLocal(nameInp, inp, name);
}
function crozzoGenerateBusinessIdLocal(nameInp, inp, name) {
  if (!inp) return;
  name = name || (nameInp && nameInp.value || '').trim();
  if (name) {
    const slug = name.replace(/[^a-zA-Z0-9]/g, '').slice(0, 16).toUpperCase();
    inp.value = 'BIZ-' + (slug || crozzoUuid().substring(0, 8).toUpperCase());
  } else {
    inp.value = 'BIZ-' + crozzoUuid().substring(0, 8).toUpperCase();
  }
  showToast('Business ID generado (nuevo negocio)', 'success');
}
function crozzoBindBusinessRegistryAutocomplete() {
  const nameEl = document.getElementById('mdBusinessName');
  const idEl = document.getElementById('mdBusinessId');
  const hintEl = document.getElementById('mdBusinessLookupHint');
  if (!nameEl || nameEl.__crozzoBizLookupBound) return;
  nameEl.__crozzoBizLookupBound = true;
  let timer = null;
  let lastQuery = '';
  function showHint(msg, ok) {
    if (!hintEl) return;
    hintEl.textContent = msg || '';
    hintEl.hidden = !msg;
    hintEl.style.color = ok ? 'var(--success, #2e7d32)' : '';
  }
  async function runLookup() {
    const name = (nameEl.value || '').trim();
    if (name.length < 2) {
      showHint('');
      lastQuery = '';
      return;
    }
    if (typeof window.crozzoLookupBusinessInCloud !== 'function') return;
    if (name !== lastQuery) showHint('Buscando en nube…', false);
    lastQuery = name;
    try {
      const hit = await window.crozzoLookupBusinessInCloud(name);
      if (!hit || !hit.businessId) {
        showHint('Sin coincidencia en nube — «Generar» crea un ID nuevo.', false);
        return;
      }
      const curId = (idEl && idEl.value || '').trim();
      if (!curId || curId === hit.businessId) {
        if (idEl) idEl.value = hit.businessId;
        showHint('✓ En nube: ' + (hit.businessName || name) + ' · ' + hit.businessId, true);
      } else {
        showHint(
          '⚠ «' + (hit.businessName || name) + '» en nube usa ' + hit.businessId + ' (distinto del ID actual).',
          false
        );
      }
    } catch (_) {
      showHint('');
    }
  }
  nameEl.addEventListener('input', function () {
    if (timer) clearTimeout(timer);
    timer = setTimeout(runLookup, 520);
  });
  nameEl.addEventListener('blur', runLookup);
}
window.crozzoBindBusinessRegistryAutocomplete = crozzoBindBusinessRegistryAutocomplete;
async function multiTestSendDemo() {
  if (!multiSyncRouter) {
    showToast('Guarda primero la configuración', 'warning');
    return;
  }
  const res = await multiSyncRouter.send({
    type: 'sync',
    data: { ping: true, ts: Date.now(), tag: 'multidevice_test' }
  });
  if (res.target === 'cloud') showToast('☁️ Enviado a Supabase Cloud', 'success');
  else if (res.target === 'p2p') showToast('🔗 Enviado al central vía P2P (WebRTC)', 'success');
  else if (res.target === 'lan') showToast('📶 Enviado a LAN Central', 'success');
  else if (res.queued) {
    if (typeof crozzoWizardTierLogLine === 'function') crozzoWizardTierLogLine('Pedido guardado — se enviará al reconectar');
  }
}
function clearMultiQueue() {
  if (!confirm('¿Eliminar todos los items en cola offline? (No afecta los ya sincronizados a la nube)')) return;
  try {
    const req = indexedDB.open('CrozzoMultiSyncDB', 2);
    req.onsuccess = (event) => {
      const db = event.target.result;
      const tx = db.transaction(['mdSyncQueue'], 'readwrite');
      tx.objectStore('mdSyncQueue').clear().onsuccess = () => {
        showToast('Cola offline limpiada', 'success');
        if (multiSyncRouter) {
          multiSyncRouter.queue = [];
          multiSyncRouter._setStatus({ pending: 0 });
        }
        db.close();
      };
    };
  } catch (e) {
    showToast('No se pudo limpiar la cola', 'error');
  }
}
