/**
 * Información de red disponible en el navegador.
 * SSID: no expuesto en la web por políticas de privacidad.
 * Gateway: heurística típica x.x.x.1 (marcar como estimado).
 */
let __crozzoNetworkInfoCache = { t: 0, data: null };
async function getNetworkInfo() {
  if (Date.now() - __crozzoNetworkInfoCache.t < 2800 && __crozzoNetworkInfoCache.data) {
    return __crozzoNetworkInfoCache.data;
  }
  const nav = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
  let connectionType = 'desconocida';
  if (nav && nav.type && nav.type !== 'unknown') {
    connectionType = nav.type;
  } else if (/Ethernet|LAN/i.test(navigator.userAgent)) {
    connectionType = 'ethernet (inferido)';
  } else if (/Mobi|Android|iPhone/i.test(navigator.userAgent)) {
    connectionType = 'wifi o datos móviles (tipo no expuesto)';
  }
  const localIp = await detectLocalIP();
  const gatewayGuess = localIp ? guessGatewayFromIp(localIp) : '';
  const out = {
    localIp,
    connectionType,
    effectiveType: nav?.effectiveType || '—',
    downlinkMbps: nav?.downlink,
    rttMs: nav?.rtt,
    saveData: nav?.saveData,
    ssid: null,
    ssidHint: 'No disponible en navegador (privacidad). Anótalo manualmente si lo necesitas.',
    gatewayGuess,
    gatewayNote: gatewayGuess ? 'Estimación habitual (.1 en la subred). Confírmalo en el router si falla el escaneo.' : ''
  };
  __crozzoNetworkInfoCache = { t: Date.now(), data: out };
  return out;
}
/**
 * Prueba hosts en la subred del equipo (muestreo + prioridad a .1, .254 y vecinos).
 * No es un escáner ICMP completo: solo HTTP /health en puertos comunes (limitaciones CORS).
 */
async function scanLocalNetwork(options = {}) {
  const ports = options.ports || [3000, 8080, 80];
  const timeoutMs = options.timeoutMs || 600;
  const maxHosts = options.maxHosts || 56;
  const local = options.baseIp || await detectLocalIP();
  if (!local) return { found: [], scanned: 0, note: 'Sin IP local; conecta Wi‑Fi/Ethernet y reintenta.' };
  const seg = local.split('.');
  if (seg.length !== 4) return { found: [], scanned: 0, note: 'IP local inválida.' };
  const prefix = `${seg[0]}.${seg[1]}.${seg[2]}`;
  const hostOrder = [];
  const push = (h) => {
    if (!hostOrder.includes(h)) hostOrder.push(h);
  };
  push(`${prefix}.1`);
  push(`${prefix}.254`);
  push(local);
  const lastOct = parseInt(seg[3], 10) || 1;
  for (let d = -4; d <= 4; d++) {
    const n = lastOct + d;
    if (n >= 1 && n <= 254) push(`${prefix}.${n}`);
  }
  for (let i = 2; i <= 40; i++) push(`${prefix}.${i}`);
  for (let i = 200; i <= 254; i++) push(`${prefix}.${i}`);
  const hosts = hostOrder.slice(0, maxHosts);
  const found = [];
  const concurrency = options.concurrency || 8;
  let scanned = 0;
  let idx = 0;
  async function probeOne(host) {
    for (const port of ports) {
      const ctrl = new AbortController();
      const t = setTimeout(() => ctrl.abort(), timeoutMs);
      try {
        await fetch(`http://${host}:${port}/health`, { method: 'GET', signal: ctrl.signal, mode: 'no-cors' });
        clearTimeout(t);
        found.push({ ip: host, port, type: `HTTP :${port} (/health)` });
        return;
      } catch (e) {
        clearTimeout(t);
      }
    }
  }
  async function worker() {
    while (idx < hosts.length) {
      const h = hosts[idx++];
      scanned++;
      await probeOne(h);
    }
  }
  await Promise.all(Array.from({ length: concurrency }, () => worker()));
  const seen = new Set();
  const uniq = found.filter((r) => {
    const k = `${r.ip}:${r.port}`;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
  return { found: uniq, scanned, note: '' };
}
/** Primera IP que responda /health en el puerto indicado (útil como “servidor A” en LAN). */
async function findServerA(port = 3000) {
  const res = await scanLocalNetwork({ ports: [port], maxHosts: 64, timeoutMs: 700 });
  return res.found[0] || null;
}
/**
 * Hub ligero en el navegador: no abre puertos TCP en la LAN.
 * - Con Supabase configurado: canal Realtime `crozzo_wizard_hub` (presencia/broadcast según tu proyecto).
 * - Sin Supabase: BroadcastChannel + marca en localStorage (misma máquina / pestañas).
 */
const CROZZO_EMBEDDED_HUB_LS = 'crozzo_embedded_hub_v1';
class CrozzoEmbeddedSyncHub {
  constructor() {
    this._channel = null;
    this._bc = typeof BroadcastChannel !== 'undefined' ? new BroadcastChannel('crozzo_lan_hub') : null;
  }
  isSupabaseReady() {
    return !!(typeof window.crozzoOnlineConfigReady === 'function' && window.crozzoOnlineConfigReady() && window.__SUPABASE);
  }
  async startAsCentral() {
    const stamp = {
      role: 'A',
      deviceId: typeof ensureCrozzoDeviceId === 'function' ? ensureCrozzoDeviceId() : '',
      ts: Date.now(),
      userAgent: typeof navigator !== 'undefined' ? navigator.userAgent.slice(0, 120) : ''
    };
    if (this.isSupabaseReady()) {
      try {
        const sb = window.__SUPABASE;
        this._channel = sb.channel('crozzo_wizard_hub');
        this._channel.subscribe((status) => {
          if (status === 'CHANNEL_ERROR') console.warn('[crozzo-hub] canal Realtime:', status);
        });
        try {
          localStorage.setItem(CROZZO_EMBEDDED_HUB_LS, JSON.stringify({ mode: 'supabase_realtime', ...stamp }));
        } catch (e) { /* ignore */ }
        return { ok: true, mode: 'supabase_realtime', detail: 'Canal Realtime iniciado. Las tablets con el mismo proyecto Supabase pueden sincronizar vía nube (véase Multi-dispositivo).' };
      } catch (e) {
        console.warn('[crozzo-hub] Supabase', e);
        try {
          if (this._channel) this._channel.unsubscribe();
        } catch (e2) { /* ignore */ }
        this._channel = null;
      }
    }
    if (this._bc) {
      try {
        this._bc.postMessage({ type: 'crozzo_central_hello', payload: stamp });
      } catch (e) { /* ignore */ }
    }
    try {
      localStorage.setItem(CROZZO_EMBEDDED_HUB_LS, JSON.stringify({ mode: 'browser_broadcast', ...stamp }));
    } catch (e) { /* ignore */ }
    return {
      ok: true,
      mode: 'browser_broadcast',
      detail: 'Sin Supabase activo: solo sincronización entre pestañas de este navegador. Configura Cloud en Super Admin para tablets reales.'
    };
  }
  stop() {
    try {
      if (this._channel) {
        this._channel.unsubscribe();
        this._channel = null;
      }
    } catch (e) { /* ignore */ }
  }
}
