  crozzoWizardTierLogLine(`Hub embebido: ${r.ok ? (r.mode || 'ok') : 'falló'} · ${r.detail || ''}`);
  showToast(r.ok ? `Hub: ${r.mode}` : 'Revisa la consola', r.ok ? 'success' : 'warning');
