async function wizardScanNetwork() {
  const status = document.getElementById('wzScanStatus');
  if (status) status.textContent = 'Escaneando subred (HTTP GET /health, muestreo limitado por el navegador)…';
  wizardCommitDraftFromInputs();
  const port = Number(wizardState.draft.port) || 3000;
  const { found, scanned, note } = await scanLocalNetwork({
    ports: [3000, 8080, 80],
    maxHosts: 56,
    timeoutMs: 650,
    concurrency: 8
  });
  const merged = [];
  const local = await detectLocalIP();
  if (local) merged.push({ ip: local, type: 'Este equipo (WebRTC)', port });
  found.forEach((f) => merged.push({ ip: f.ip, type: f.type, port: f.port }));
  const seen = new Set();
  wizardState.scanResults = merged.filter((c) => {
    if (seen.has(c.ip)) return false;
    seen.add(c.ip);
    return true;
  });
  if (status) {
    status.textContent = note || `Muestreo ~${scanned} hosts · ${found.length} respuesta(s) /health · revisa la lista.`;
  }
  if (!wizardState.scanResults.length) {
    wizardState.scanResults = [
      { ip: '192.168.137.1', type: 'Hotspot Windows (probar)', port },
      { ip: '192.168.43.1', type: 'Hotspot Android (probar)', port }
    ];
    if (status) status.textContent += ' · Mostrando IPs típicas de hotspot para prueba manual.';
  }
  wizardRender();
}
