async function wizardTryParseConfig(text) {
  if (!text) return;
  try {
    const obj = JSON.parse(text);
    const QR = window.CrozzoQRPairing || window.QRPairing;
    let localLoc = '';
    if (window.CrozzoNetworkGuard) {
      localLoc = await CrozzoNetworkGuard.ensureLocationIdForPayload({
        networkSsidNote: wizardState.draft.ssidNote || '',
        role: 'B',
        port: wizardState.draft.port || 3000
      });
    }
    if (obj && obj.type === 'CROZZO_PAIRING' && QR) {
      const v = QR.validate(obj, { localLocationId: localLoc, myDeviceId: ensureCrozzoDeviceId() });
      if (!v.ok) {
        showToast(v.message || 'QR inválido', 'warning');
        return;
      }
      const ip = String(v.data.centralIp || '').trim();
      const port = Number(v.data.port) || 3000;
      if (ip) {
        const ipInput = document.getElementById('wzCentralIp');
        const portInput = document.getElementById('wzPortB');
        if (ipInput) ipInput.value = ip;
        if (portInput) portInput.value = String(port);
        wizardState.draft.centralIp = ip;
        wizardState.draft.port = port;
        wizardState.draft.role = 'B';
        wizardState.role = 'B';
        if (v.data.locationId) {
          wizardState.draft.locationId = v.data.locationId;
          const locInp = document.getElementById('wzLocationId');
          if (locInp) locInp.value = v.data.locationId;
        }
        showToast(`✅ QR del central · ${ip}:${port}`, 'success');
        if (typeof crozzoWizardTierLogLine === 'function') {
          crozzoWizardTierLogLine(`QR v2 · ${ip}:${port} · sede ${String(v.data.locationId || '').slice(0, 24)}`);
        }
        wizardRunHealthCheckB();
      }
      return;
    }
    if (obj && obj.type === 'crozzo_pair') {
      const ip = String(obj.centralIp || obj.serverIp || '').trim();
      const port = Number(obj.port) || 3000;
      if (ip) {
        const ipInput = document.getElementById('wzCentralIp');
        const portInput = document.getElementById('wzPortB');
        if (ipInput) ipInput.value = ip;
        if (portInput) portInput.value = String(port);
        wizardState.draft.centralIp = ip;
        wizardState.draft.port = port;
        showToast(`Configuración leída (legacy): ${ip}:${port}`, 'success');
      }
    }
  } catch (e) {
    // silencioso: el usuario sigue escribiendo
  }
}
function wizardCopyEmpresaDian() {
  const emp = config.getEmpresa();
  const dian = config.getDian();
  wizardState.draft.dianNit = emp.nit || wizardState.draft.dianNit;
  wizardState.draft.dianResolution = dian.resolucion || wizardState.draft.dianResolution;
  if (dian.rangoDesde && dian.rangoHasta) {
    wizardState.draft.dianRange = `${dian.rangoDesde} - ${dian.rangoHasta}`;
  }
  if (!wizardState.draft.businessName) {
    wizardState.draft.businessName = emp.nombreComercial || emp.razonSocial || '';
  }
  showToast('Datos copiados desde Empresa y DIAN', 'success');
  wizardRender();
}
