async function wizardTestSend() {
  // Asegura que la config esté guardada antes de enviar
  if (!wizardState.completed) {
    wizardFinish();
  }
  if (!crozzoSyncRouter) {
    const fullPayload = buildCrozzoConfigPayload();
    crozzoSyncRouter = new CrozzoSyncRouter(fullPayload);
  }
  wizardState.testSend = { state: 'pending', message: 'Enviando pedido demo…' };
  wizardRender();
  const demoOrder = {
    type: 'order',
    data: {
      origen: 'wizard_test',
      tablet: wizardState.draft.tabletName || 'Tablet sin nombre',
      area: wizardState.draft.tabletArea || '',
      total: 1000,
      items: [{ sku: 'DEMO-001', nombre: 'Pedido de prueba', cantidad: 1, precio: 1000 }],
      ts: Date.now()
    }
  };
  const res = await crozzoSyncRouter.send(demoOrder);
  if (res && res.success) {
    wizardState.testSend = { state: 'ok', message: 'Pedido enviado al central correctamente.' };
  } else if (res && res.queued) {
    wizardState.testSend = { state: 'queued', message: 'Pedido guardado en la cola offline. Se sincronizará al reconectar.' };
  } else {
    wizardState.testSend = { state: 'fail', message: 'No se pudo enviar el pedido demo.' };
  }
  wizardRender();
}
// --- Banner inicial cuando no hay configuración ---
function wizardMaybeShowInitialBanner() {
  if (wizardHasCompletedConfig()) return;
  if (document.getElementById('wizardInitBanner')) return;
  const stored = wizardLoadStoredState();
  const resume = !!(stored && stored.skipped && !stored.completed);
  const banner = document.createElement('div');
  banner.id = 'wizardInitBanner';
  banner.className = 'wizard-banner';
  banner.innerHTML = `
    <span>🔧</span>
    <div>${resume ? 'El asistente quedó a medias. Puedes reanudarlo sin perder el avance guardado en este equipo.' : 'Aún no has configurado este dispositivo.'}</div>
    <button class="btn btn-primary" type="button" onclick="document.getElementById('wizardInitBanner')?.remove(); wizardOpen();">${resume ? 'Reanudar asistente' : 'Configurar ahora'}</button>
    <button class="btn btn-outline" type="button" aria-label="Cerrar" onclick="document.getElementById('wizardInitBanner')?.remove();">✕</button>
  `;
  document.body.appendChild(banner);
}
// Cierre por click fuera del shell
document.addEventListener('click', (e) => {
  const overlay = document.getElementById('wizardOverlay');
  if (!overlay) return;
  if (!overlay.classList.contains('active')) return;
  if (e.target === overlay) wizardClose();
});
