function initConfigDian() {
  const fechaVenc = document.getElementById('cfgFechaVencimiento');
  if (fechaVenc) {
    const venc = new Date(fechaVenc.value);
    const ahora = new Date();
    const diff = (venc - ahora) / (1000 * 60 * 60 * 24);
    if (diff < 30 && diff > 0 && fechaVenc.value) {
      showToast(`⚠️ La resolución vence en ${Math.ceil(diff)} días`, 'warning');
    }
  }
}
function saveDianConfig() {
  const resolucion = document.getElementById('cfgResolucion')?.value || '';
  const rangoDesde = parseInt(document.getElementById('cfgRangoDesde')?.value) || 0;
  const rangoHasta = parseInt(document.getElementById('cfgRangoHasta')?.value) || 0;
  
  if (rangoHasta && rangoDesde > rangoHasta) {
    showToast('El rango "Desde" no puede ser mayor que "Hasta"', 'error');
    return;
  }
  
  config.set('dian', {
    resolucion,
    prefijo: document.getElementById('cfgPrefijo')?.value || '',
    rangoDesde,
    rangoHasta,
    fechaDesde: document.getElementById('cfgFechaDesde')?.value || '',
    fechaVencimiento: document.getElementById('cfgFechaVencimiento')?.value || '',
    tipoDocumento: document.getElementById('cfgTipoDoc')?.value || '01',
    tipoOperacion: document.getElementById('cfgTipoOperacion')?.value || '01'
  });
  
  config.addAudit('config_dian_actualizada', `Resolución ${resolucion} - Rango ${rangoDesde}-${rangoHasta}`);
  showToast('Configuración DIAN guardada', 'success');
}
