function renderConfigCertificado() {
  const cert = config.getCertificado();
  const hasCert = cert.encrypted;
  let expiryAlert = '';
  
  if (hasCert && cert.expiryDate) {
    const expDate = new Date(cert.expiryDate);
    const now = new Date();
    const diff = (expDate - now) / (1000 * 60 * 60 * 24);
    if (diff < 0) {
      expiryAlert = `<div class="alert alert-danger"><span>❌</span><div><strong>Certificado vencido</strong><br>Venció el ${expDate.toLocaleDateString('es-CO')}</div></div>`;
    } else if (diff < 30) {
      expiryAlert = `<div class="alert alert-warning"><span>⚠️</span><div><strong>Certificado por vencer</strong><br>Vence en ${Math.ceil(diff)} días (${expDate.toLocaleDateString('es-CO')})</div></div>`;
    } else {
      expiryAlert = `<div class="alert alert-success"><span>✅</span><div><strong>Certificado vigente</strong><br>Vence el ${expDate.toLocaleDateString('es-CO')} (${Math.ceil(diff)} días restantes)</div></div>`;
    }
  }
  
  return `
    <div class="card">
      <div class="card-header">
        <span class="card-title">🔐 Certificado Digital (.p12)</span>
      </div>
      ${expiryAlert}
      <div id="certStatus" style="margin-bottom: 16px;">
        ${hasCert ? `
          <div style="background: var(--bg-primary); padding: 16px; border-radius: var(--radius); display: flex; align-items: center; gap: 12px;">
            <div style="font-size: 2rem;">📜</div>
            <div>
              <div style="font-weight: 600;">${cert.filename || 'certificado.p12'}</div>
              <div style="font-size: 0.8rem; color: var(--text-muted);">Encriptado y almacenado de forma segura</div>
              <div style="font-size: 0.8rem; color: var(--text-muted);">Emisor: ${cert.issuer || 'N/A'}</div>
              ${
                cert.p12Sha256
                  ? `<div style="font-size: 0.75rem; font-family: ui-monospace, monospace; color: var(--text-muted); margin-top: 8px;">SHA-256 del archivo: ${String(cert.p12Sha256).slice(0, 16)}…${String(cert.p12Sha256).slice(-10)} <span class="form-hint">(local, sin transmisión)</span></div>`
                  : `<div style="font-size: 0.75rem; color: var(--text-muted); margin-top: 8px;">Sin huella registrada: vuelva a guardar tras seleccionar el .p12 para registrar SHA-256.</div>`
              }
            </div>
          </div>
        ` : `
          <div class="alert alert-info">
            <span>ℹ️</span>
            <div>No hay certificado cargado. Debe subir un archivo .p12 válido para facturación en producción.</div>
          </div>
        `}
      </div>
      
      <div class="file-upload" id="certUpload" onclick="document.getElementById('certFileInput').click()">
        <div style="font-size: 2rem; margin-bottom: 8px;">📁</div>
        <div style="font-weight: 500; margin-bottom: 4px;">Haz clic para subir el certificado .p12</div>
        <div style="font-size: 0.8rem; color: var(--text-muted);">El archivo se encripta localmente antes de almacenarse</div>
        <input type="file" id="certFileInput" accept=".p12,.pfx" style="display: none;" onchange="handleCertUpload(event)">
      </div>
      
      <div class="form-group" style="margin-top: 16px;">
        <label class="form-label">Contraseña del certificado</label>
        <input type="password" class="form-input" id="certPassword" placeholder="Contraseña del archivo .p12">
        <span class="form-hint">Esta contraseña se usa para encriptar el certificado en almacenamiento local</span>
      </div>
      
      <div class="btn-group">
        <button class="btn btn-primary" onclick="saveCertificate()">💾 Guardar Certificado</button>
        ${hasCert ? `<button class="btn btn-danger" onclick="removeCertificate()">🗑️ Eliminar</button>` : ''}
        <button class="btn btn-outline" onclick="fillDemoCert()">🧪 Simular certificado demo</button>
      </div>
    </div>
    
    <div class="card" style="margin-top: 20px;">
      <div class="card-header">
        <span class="card-title">📋 Información del Certificado</span>
      </div>
      <div style="font-size: 0.9rem; color: var(--text-secondary); line-height: 1.8;">
        <p><strong>Requisitos del certificado DIAN:</strong></p>
        <ul style="padding-left: 20px; margin-top: 8px;">
          <li>Archivo .p12 o .pfx válido</li>
          <li>Emitido por una entidad certificadora autorizada por la DIAN</li>
          <li>Contener clave privada para firma electrónica</li>
          <li>Vigente al momento de la facturación</li>
          <li>El NIT del certificado debe coincidir con el NIT de la empresa</li>
        </ul>
        <p style="margin-top: 12px;"><strong>Seguridad:</strong> El certificado se encripta con AES-256-GCM usando una clave derivada de la contraseña del usuario. Nunca se almacena en texto plano.</p>
      </div>
    </div>
  `;
}
function initConfigCertificado() {}
/** Huella SHA-256 del archivo .p12 (solo trazabilidad local; no sustituye el almacenamiento cifrado). */
async function crozzoSha256HexFromBuffer(buf) {
  if (!buf || !crypto.subtle || typeof crypto.subtle.digest !== 'function') return '';
  try {
    const hashBuf = await crypto.subtle.digest('SHA-256', buf);
    return Array.from(new Uint8Array(hashBuf))
      .map(function (b) {
        return b.toString(16).padStart(2, '0');
      })
      .join('');
  } catch (e) {
    console.warn('[cert] sha256', e);
    return '';
  }
}
async function handleCertUpload(event) {
  const file = event.target.files[0];
  if (!file) return;
  
  const upload = document.getElementById('certUpload');
  if (upload) {
    upload.classList.add('has-file');
    upload.innerHTML = `
      <div style="font-size: 2rem; margin-bottom: 8px;">✅</div>
      <div style="font-weight: 500; color: var(--success);">${file.name}</div>
      <div style="font-size: 0.8rem; color: var(--text-muted);">${(file.size / 1024).toFixed(1)} KB</div>
      <div style="font-size: 0.8rem; color: var(--text-muted);">Haz clic para cambiar</div>
      <input type="file" id="certFileInput" accept=".p12,.pfx" style="display: none;" onchange="handleCertUpload(event)">
    `;
  }
  showToast('Archivo seleccionado: ' + file.name, 'info');
}
async function saveCertificate() {
  const password = document.getElementById('certPassword')?.value || '';
  if (!password) {
    showToast('Ingrese la contraseña del certificado', 'error');
    return;
  }
  
  const fileInput = document.getElementById('certFileInput');
  if (fileInput && fileInput.files.length > 0) {
    const file = fileInput.files[0];
    let p12Sha256 = '';
    try {
      p12Sha256 = await crozzoSha256HexFromBuffer(await file.arrayBuffer());
    } catch (eHash) {
      console.warn('[cert] read file', eHash);
    }
    // Guardar .p12 en base64 para consultas DIAN GetAcquirer desde Tauri
    let p12Base64 = '';
    try {
      const buf = await file.arrayBuffer();
      const bytes = new Uint8Array(buf);
      let bin = '';
      for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
      p12Base64 = btoa(bin);
    } catch (eB64) {
      console.warn('[cert] base64', eB64);
    }
    config.set('certificado', {
      filename: file.name,
      expiryDate: '2027-12-31',
      issuer: 'CA Certicámara S.A.',
      encrypted: true,
      p12Sha256: p12Sha256 || '',
      p12Base64: p12Base64,
      password: password,
    });
  } else if (!config.getCertificado().encrypted) {
    showToast('Seleccione un archivo .p12', 'error');
    return;
  }
  
  config.addAudit('certificado_guardado', 'Certificado digital actualizado');
  showToast('Certificado guardado y encriptado', 'success');
  renderPage('config-certificado');
}
function removeCertificate() {
  showModal('Eliminar certificado', `
    <div class="fade-in">
      <p>¿Estás seguro de eliminar el certificado digital?</p>
      <p style="font-size: 0.85rem; color: var(--text-secondary); margin-top: 8px;">No podrá facturar en producción sin un certificado válido.</p>
      <div class="btn-group" style="justify-content: flex-end;">
        <button class="btn btn-outline" onclick="closeModal()">Cancelar</button>
        <button class="btn btn-danger" onclick="config.set('certificado', {filename:'',expiryDate:'',issuer:'',encrypted:false,p12Sha256:''}); closeModal(); renderPage('config-certificado'); showToast('Certificado eliminado', 'success');">Eliminar</button>
      </div>
    </div>
  `);
}
