// CONFIG PROVEEDOR PAGE
// ==========================================
function renderConfigProveedor() {
  const prov = config.getProveedor();
  const providers = [
    { type: 'mock', name: 'Mock / Demo', icon: '🧪', desc: 'Simulación para pruebas sin conexión real' },
    { type: 'dataico', name: 'Dataico', icon: '🔌', desc: 'API REST moderna, webhooks RADIAN' },
    { type: 'siigo', name: 'Siigo Nube', icon: '☁️', desc: 'Plataforma contable y de facturación' },
    { type: 'facturama', name: 'Facturama', icon: '📄', desc: 'Solución de facturación electrónica' }
  ];
  
  return `
    <div class="card">
      <div class="card-header">
        <span class="card-title">🔌 Proveedor de Facturación Electrónica</span>
      </div>
      <div class="provider-grid" style="margin-bottom: 24px;">
        ${providers.map(p => `
          <div class="provider-card ${prov.type === p.type ? 'selected' : ''}" onclick="selectProvider('${p.type}')">
            <div class="provider-icon">${p.icon}</div>
            <div class="provider-name">${p.name}</div>
            <div class="provider-desc">${p.desc}</div>
          </div>
        `).join('')}
      </div>
      
      ${prov.type !== 'mock' ? `
        <div class="form-grid" id="providerConfig">
          <div class="form-group">
            <label class="form-label">API Key</label>
            <input type="text" class="form-input" id="provApiKey" value="${prov.apiKey || ''}" placeholder="sk_live_xxxxxxxxxxxxx">
          </div>
          <div class="form-group">
            <label class="form-label">API Secret</label>
            <input type="password" class="form-input" id="provApiSecret" value="${prov.apiSecret || ''}" placeholder="••••••••">
          </div>
          <div class="form-group">
            <label class="form-label">Base URL</label>
            <input type="text" class="form-input" id="provBaseUrl" value="${prov.baseUrl || ''}" placeholder="https://api.dataico.com/v1">
          </div>
          <div class="form-group">
            <label class="form-label">Ambiente</label>
            <select class="form-select" id="provAmbiente">
              <option value="test" ${prov.ambiente === 'test' ? 'selected' : ''}>Test / Sandbox</option>
              <option value="prod" ${prov.ambiente === 'prod' ? 'selected' : ''}>Producción</option>
            </select>
          </div>
        </div>
        <div class="btn-group">
          <button class="btn btn-primary" onclick="saveProviderConfig()">💾 Guardar</button>
          <button class="btn btn-outline" onclick="testProviderConnection()">🔗 Probar Conexión</button>
        </div>
      ` : `
        <div class="alert alert-info">
          <span>ℹ️</span>
          <div><strong>Modo Mock activo</strong><br>Las facturas se simulan localmente sin conexión a ningún proveedor externo. Ideal para desarrollo y pruebas.</div>
        </div>
        <div class="btn-group">
          <button class="btn btn-primary" onclick="saveProviderConfig()">💾 Guardar</button>
        </div>
      `}
    </div>
  `;
}
function initConfigProveedor() {}
function selectProvider(type) {
  config.set('proveedor', { ...config.getProveedor(), type });
  renderPage('config-proveedor');
}
function saveProviderConfig() {
  const prov = config.getProveedor();
  const updated = {
    ...prov,
    apiKey: document.getElementById('provApiKey')?.value || prov.apiKey,
    apiSecret: document.getElementById('provApiSecret')?.value || prov.apiSecret,
    baseUrl: document.getElementById('provBaseUrl')?.value || prov.baseUrl,
    ambiente: document.getElementById('provAmbiente')?.value || prov.ambiente
  };
  config.set('proveedor', updated);
  config.addAudit('proveedor_actualizado', `Proveedor: ${updated.type}`);
  showToast('Configuración del proveedor guardada', 'success');
}
async function testProviderConnection() {
  const prov = config.getProveedor();
  showToast(`Probando conexión con ${prov.type}...`, 'info');
  
  await new Promise(r => setTimeout(r, 1500));
  
  if (prov.apiKey) {
    showToast(`✅ Conexión exitosa con ${prov.type}`, 'success');
  } else {
    showToast('⚠️ Configure las credenciales antes de probar', 'warning');
  }
}
