              <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                <strong>📺 ${a.nombre}</strong>
                <span class="badge badge-info">${crozzoGetDevicePantallaId() === a.id ? 'Activa aquí' : 'Pantalla'}</span>
              </div>
