// ACTUALIZACIONES DEL SISTEMA (Super Admin) — UI en HTML; lógica en CrozzoSystemUpdates.js
// ==========================================
function renderActualizacionesSistema() {
  var vCur =
    typeof window.CROZZO_APP_VERSION !== 'undefined' ? window.CROZZO_APP_VERSION : 'v1.0.0';
  var manifestDefault =
    'https://raw.githubusercontent.com/kenny14ramirez-prog/Principal/main/releases/latest.json';
  return (
    '<section id="actualizaciones-sistema" class="content-section crozzo-updates-section">' +
    '<div class="card">' +
    '<div class="card-header">' +
    '<span class="card-title">Actualizaciones del sistema</span>' +
    '<span class="badge" style="background:transparent;border:1px solid var(--border);color:var(--text-muted);">Super Admin</span>' +
    '</div>' +
    '<p class="form-hint" style="margin:0 0 var(--space-3);">OTA: <code>registry.json</code> en <code>main</code> (avisos). Instalador: <code>latest.json</code> del <strong>GitHub Release</strong> (tag <code>v*</code>); en escritorio, <strong>Instalar</strong> descarga el .exe firmado.</p>' +
    '<p style="margin:0 0 var(--space-2);">Versión del ejecutable (.exe): <strong id="crozzoUpdatesBinaryVersionLabel">—</strong></p>' +
    '<p style="margin:0 0 var(--space-4);">Versión OTA registrada: <span class="crozzo-updates-version" id="crozzoUpdatesVersionLabel">' +
    escUserAttr(vCur) +
    '</span></p>' +
    '<p class="form-hint" style="margin:0 0 var(--space-4);">Los cambios de código locales requieren <strong>Sincronizar frontend</strong> (menú herramientas) y recompilar el .exe, o publicar un release nuevo en GitHub. El JSON en <code>main</code> solo muestra avisos; no sustituye el instalador.</p>' +
    '<div class="form-group" style="margin-bottom:var(--space-4);">' +
    '<label class="form-label" for="crozzoUpdateManifestUrl">URL del manifiesto (raw GitHub)</label>' +
    '<input type="url" class="form-input" id="crozzoUpdateManifestUrl" placeholder="' +
    escUserAttr(manifestDefault) +
    '" value="" autocomplete="off">' +
    '<p class="form-hint" style="margin:6px 0 0;">Por defecto: <code>releases/latest.json</code> en el repo Principal. Guarde y use <strong>Comprobar ahora</strong>.</p>' +
    '</div>' +
    '<div class="crozzo-updates-actions" style="margin-bottom:var(--space-4);flex-wrap:wrap;gap:8px;display:flex;">' +
    '<button type="button" class="btn btn-primary" id="crozzoUpdateCheckNow">Comprobar ahora</button>' +
    '<button type="button" class="btn btn-outline" id="crozzoUpdateSaveManifestUrl">Guardar URL</button>' +
    '<button type="button" class="btn btn-outline" id="crozzoUpdateResetAlerts">Restablecer avisos ocultos</button>' +
    '<button type="button" class="btn btn-outline" onclick="crozzoOpenAppDownloadQr()">📱 QR app actualizada</button>' +
    '</div>' +
    '<p class="form-hint" id="crozzoUpdateCheckStatus" style="margin:0 0 var(--space-4);min-height:1.2em;"></p>' +
    '<label class="form-label" style="display:flex;align-items:center;gap:8px;margin:0 0 var(--space-4);cursor:pointer;">' +
    '<input type="checkbox" id="crozzoUpdateDesktopAutoInstall" checked>' +
    '<span>Auto-instalación en PC (Windows/Mac) — activa por defecto; desmarque solo en desarrollo local.</span>' +
    '</label>' +
    '</div>' +
    '<div class="card" style="margin-top:14px;">' +
    '<div class="card-header"><span class="card-title">Registro remoto (GitHub)</span></div>' +
    '<div id="crozzoUpdateRegistryTable" class="form-hint">Abra esta página o pulse Comprobar ahora.</div>' +
    '</div>' +
    '<div class="card" style="margin-top:14px;">' +
    '<div class="card-header"><span class="card-title">Historial en este equipo</span></div>' +
    '<div id="crozzoUpdateLocalLog"></div>' +
    '</div>' +
    '<div class="card" style="margin-top:14px;">' +
    '<div class="card-header"><span class="card-title">Simulación local</span></div>' +
    '<div class="crozzo-updates-panel">' +
    '<p class="form-hint" style="margin:0 0 var(--space-2);">Simulación local (sin GitHub):</p>' +
    '<div class="crozzo-updates-actions">' +
    '<button type="button" class="btn btn-success" data-crozzo-sim-update="normal">Simular actualización normal</button>' +
    '<button type="button" class="btn btn-danger" data-crozzo-sim-update="critica">Simular actualización crítica</button>' +
    '</div>' +
    '</div>' +
    '</div>' +
    '</section>'
  );
}
window.renderActualizacionesSistema = renderActualizacionesSistema;
// ==========================================
// CONFIGURACIÓN DEL SISTEMA (Super Admin)
// ==========================================
function crozzoSeguridadShiftLabel() {
  try {
    if (window.CrozzoHoneypotSim && typeof CrozzoHoneypotSim.getShiftContext === 'function') {
      return CrozzoHoneypotSim.getShiftContext(false).label;
    }
  } catch (_) {}
  return '—';
}
function renderConfigSeguridad() {
  const u = getCurrentUser();
  const seg = config.get('seguridad') || { requiereLogin: true };
  const requiere = seg.requiereLogin !== false;
  const idleMin = typeof seg.sessionIdleMinutes === 'number' ? seg.sessionIdleMinutes : 30;
  const hp = (window.CrozzoAuthSecurity && CrozzoAuthSecurity.normalizeHoneypot(seg.honeypot)) || seg.honeypot || {};
  const hpLock =
    window.CrozzoAuthSecurity && typeof CrozzoAuthSecurity.crozzoHoneypotLockActive === 'function'
      ? CrozzoAuthSecurity.crozzoHoneypotLockActive(seg)
      : { locked: false };
  const legendReady = !!(hp.unlockCodeHash && hp.unlockCodeSalt);
  const shiftLbl = crozzoSeguridadShiftLabel();
  const vpScale =
    typeof getComputedStyle === 'function'
      ? getComputedStyle(document.documentElement).getPropertyValue('--crozzo-system-scale').trim() || '1'
      : '1';
  const vpH =
    typeof getComputedStyle === 'function'
      ? getComputedStyle(document.documentElement).getPropertyValue('--crozzo-vh').trim()
      : '';
  const cuarentenaCls = hpLock.legendary
    ? 'seg-status-danger'
    : hpLock.locked
      ? 'seg-status-warn'
      : 'seg-status-ok';
  const cuarentenaVal = hpLock.legendary
    ? 'Cuarentena legendaria activa'
    : hpLock.locked
      ? 'Bloqueo temporal (~' + (hpLock.minutos || 0) + ' min)'
      : 'Sin bloqueo por intrusión';
  const hpProdStrict = hp.produccionEstricta === true;
  const trampaCls = 'seg-status-ok';
  const trampaVal =
    'Siempre activa · ' +
    (hp.decoys || []).length +
    ' cebos' +
    (hpProdStrict ? ' · producción estricta' : '');
  const lastEvt = hp.lastTripAt
    ? `${escUserAttr(hp.lastTripId || '—')}${hp.lastDecoyUser ? ' · ' + escUserAttr(hp.lastDecoyUser) : ''} · ${escUserAttr(String(hp.lastTripAt).slice(0, 19).replace('T', ' '))}`
    : 'Ningún evento registrado';
  const decoyOptions = (hp.decoys || [])
    .map(d => `<option value="${escUserAttr(d.user)}">${escUserAttr(d.user)} — ${escUserAttr(d.label)}</option>`)
    .join('');
  const localHint =
    typeof window.__crozzoIsLocalDataMode === 'function' && window.__crozzoIsLocalDataMode()
      ? '<p class="form-hint" style="margin:8px 0 0;">Modo local: cuenta de soporte del fabricante (no listada en Usuarios). Clave de fábrica solo en la guía de instalación.</p>'
      : '';
  const sesion = u
    ? `<strong>${escUserAttr(u.nombre)}</strong> · <span class="badge">${escUserAttr(rolFuncionalLabel(u.rol))}</span>`
    : '<em>— Sin sesión activa —</em>';
  return `
    <div class="card">
      <div class="card-header">
        <span class="card-title">🔐 Sesión y acceso</span>
        <span class="badge" style="background:transparent;border:1px solid var(--border);color:var(--text-muted);">Super Admin</span>
      </div>
      <div class="alert alert-info" style="margin-bottom:14px;">
        <span style="font-size:1.1rem;">👤</span>
        <div>
          <div style="font-size:0.78rem;color:var(--text-muted);">Sesión activa</div>
          <div>${sesion}</div>
          ${localHint}
        </div>
      </div>
      <div class="form-group" style="background:rgba(15,23,42,0.35);padding:14px;border-radius:var(--radius);border:1px solid var(--border);">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
          <div>
            <strong>Login al iniciar la app</strong>
            <p class="form-hint" style="margin:4px 0 0;">
              Obligatorio en todo momento. Los usuarios del negocio se gestionan en
              <strong>Configuración → Usuarios</strong> (rol admin).
            </p>
          </div>
          <span class="badge seg-status-ok" style="white-space:nowrap;">Siempre activo</span>
        </div>
      </div>
      <div class="btn-group" style="margin-top:14px; gap:8px; flex-wrap:wrap;">
        <button class="btn btn-outline" onclick="handleLogout()">🚪 Cerrar sesión</button>
        <button class="btn btn-outline" onclick="showLoginOverlay()">👀 Probar pantalla de login</button>
        <button type="button" class="btn btn-outline" onclick="navigateTo('config-usuarios')">👥 Ir a Usuarios</button>
        <button type="button" class="btn btn-outline" onclick="navigateTo('config-multidispositivo')">📡 Multi-dispositivo</button>
      </div>
    </div>
    <div class="card" style="margin-top:14px;">
      <div class="card-header">
        <span class="card-title">⏱️ Cierre por inactividad</span>
      </div>
      <p class="form-hint" style="margin:0 0 10px;">
        Tras este tiempo sin uso del ratón o teclado, se cierra la sesión y vuelve la pantalla de login (0 = desactivado).
      </p>
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
        <input type="number" class="form-input" id="cfgSessionIdle" min="0" max="480" step="5" value="${idleMin}" style="max-width:100px;">
        <span class="form-hint" style="margin:0;">minutos</span>
        <button type="button" class="btn btn-outline" onclick="setSessionIdleMinutes(document.getElementById('cfgSessionIdle')?.value)">Guardar</button>
      </div>
    </div>
    <div class="card" style="margin-top:14px;">
      <div class="card-header">
        <span class="card-title">🛡️ Protección actual del sistema</span>
      </div>
      <p class="form-hint" style="margin:0 0 8px;">
        Resumen en tiempo real (solo Super Admin). Los intrusos <strong>no</strong> ven esta pantalla; la secuencia que ven usa textos operativos creíbles, sin mencionar “emulación” ni “datos falsos”.
      </p>
      <table class="seg-status-table" role="table" aria-label="Estado de protección">
        <tbody>
          <tr>
            <th scope="row">Login al iniciar</th>
            <td class="seg-status-ok">Siempre requerido</td>
          </tr>
          <tr>
            <th scope="row">Cierre por inactividad</th>
            <td>${idleMin ? idleMin + ' min' : 'Desactivado'}</td>
          </tr>
          <tr>
            <th scope="row">Contraseñas locales</th>
            <td class="seg-status-ok">PBKDF2 · 120 k iteraciones</td>
          </tr>
          <tr>
            <th scope="row">Intentos fallidos</th>
            <td>5 intentos → bloqueo 5 min</td>
          </tr>
          <tr>
            <th scope="row">Trampa honeypot</th>
            <td class="${trampaCls}">${escUserAttr(trampaVal)}</td>
          </tr>
          <tr>
            <th scope="row">Cuarentena / bloqueo</th>
            <td class="${cuarentenaCls}">${escUserAttr(cuarentenaVal)}</td>
          </tr>
          <tr>
            <th scope="row">Código leyenda</th>
            <td class="${legendReady ? 'seg-status-ok' : 'seg-status-warn'}">${legendReady ? 'Configurado (hash en disco)' : 'Pendiente al iniciar app'}</td>
          </tr>
          <tr>
            <th scope="row">Contexto horario (teatro)</th>
            <td class="seg-status-muted">${escUserAttr(shiftLbl)}</td>
          </tr>
          <tr>
            <th scope="row">Pantalla / escala</th>
            <td class="seg-status-muted">${escUserAttr(vpScale !== '1' ? '×' + vpScale : '100%')}${vpH ? ' · ' + escUserAttr(vpH) : ''}</td>
          </tr>
          <tr>
            <th scope="row">Último evento de intrusión</th>
            <td class="seg-val--compact">${lastEvt} · total ${hp.tripCount || 0}</td>
          </tr>
        </tbody>
      </table>
      ${
        hpLock.locked
          ? hpLock.legendary
            ? `<div class="alert alert-warning" style="margin:12px 0 0;">🛡️ <strong>Cuarentena legendaria</strong> — libere con el código en <code>herramientas/CROZZO_LEYENDA_DESBLOQUEO.txt</code> o el .bat recordatorio.</div>`
            : `<div class="alert alert-warning" style="margin:12px 0 0;">🔒 Bloqueo temporal activo (~${hpLock.minutos} min).</div>`
          : ''
      }
      <div class="form-group" style="margin-top:14px;padding:12px;border:1px solid var(--border);border-radius:var(--radius);background:rgba(59,130,246,0.06);">
        <strong style="font-size:0.88rem;">🎬 Recrear secuencia de protección (vista previa)</strong>
        <p class="form-hint" style="margin:6px 0 10px;">
          Reproduce el teatro que vería un atacante con un usuario señuelo. <strong>No bloquea</strong> el sistema ni incrementa la cuarentena.
        </p>
        <div class="seg-preview-row">
          <div class="form-group">
            <label class="form-label">Usuario señuelo</label>
            <select class="form-select" id="cfgHpPreviewDecoy">${decoyOptions}</select>
          </div>
          <div class="seg-preview-actions">
            <div class="seg-hp-mode-group" role="radiogroup" aria-label="Duración de la vista previa">
              <label class="seg-hp-mode" title="Teatro y app simulada, ~15 s">
                <input type="radio" name="cfgHpPreviewMode" value="short" checked>
                <span>Rápida</span>
              </label>
              <label class="seg-hp-mode" title="Incluye sincronización y cierre simulado">
                <input type="radio" name="cfgHpPreviewMode" value="full">
                <span>Completa</span>
              </label>
            </div>
            <button type="button" class="btn btn-primary" onclick="crozzoHoneypotAdminTheaterPreview()">▶ Iniciar vista previa</button>
          </div>
        </div>
      </div>
    </div>
    <div class="card" style="margin-top:14px;">
      <div class="card-header">
        <span class="card-title">🎭 Configuración honeypot</span>
      </div>
      <p class="form-hint" style="margin:0 0 10px;">
        Cebos con errores engañosos (3 intentos → trampa). Flujo real: POS falso navegable → alertas → pantalla de bloqueo → cuarentena.
        La trampa <strong>no se puede desactivar</strong>; el Super Admin puede emular la secuencia con la vista previa de arriba.
        Liberación solo con código en <code>herramientas/</code> (la contraseña de soporte sola no basta).
      </p>
      <div class="alert alert-info" style="margin:0 0 12px;">
        <strong>Prueba rápida (cebo):</strong> usuario <code>payaso</code> · contraseña <code>payaso123</code>
        (rol admin señuelo; no existe en Usuarios reales). También vale <code>PAYASO</code> en mayúsculas.
      </div>
      ${
        Array.isArray(hp.tripLog) && hp.tripLog.length
          ? `<p class="form-hint" style="margin:0 0 12px;color:#f87171;">Registro forense: ${hp.tripLog.length} evento(s) de trampa. Ver también Auditoría → eventos de trampa.</p>`
          : ''
      }
      <div class="form-group" style="padding:12px;border:1px solid var(--border);border-radius:var(--radius);">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:10px;">
          <div>
            <strong>Trampa honeypot</strong>
            <p class="form-hint" style="margin:4px 0 0;">Siempre activa. No se puede desactivar; use la vista previa de arriba para emular sin bloquear.</p>
          </div>
          <span class="badge seg-status-ok">Obligatoria</span>
        </div>
        <details style="margin:10px 0;">
          <summary class="form-hint" style="cursor:pointer;">Ver lista de usuarios señuelo (${(hp.decoys || []).length})</summary>
          <div class="users-table-wrap" style="margin:10px 0;max-height:220px;overflow:auto;">
            <table class="users-table" style="font-size:0.78rem;">
              <thead><tr><th>Usuario</th><th>Clave cebo</th><th>Rol</th><th>Etiqueta</th></tr></thead>
              <tbody>
                ${(hp.decoys || []).map(d => `
                  <tr>
                    <td><code>${escUserAttr(d.user)}</code></td>
                    <td><code>${escUserAttr(d.pass)}</code></td>
                    <td>${escUserAttr(d.rol)}</td>
                    <td>${escUserAttr(d.label)}</td>
                  </tr>
                `).join('')}
              </tbody>
            </table>
          </div>
        </details>
        <div class="form-grid" style="gap:10px;">
          <div class="form-group">
            <label class="form-label">Teatro inicial (seg)</label>
            <input type="number" class="form-input" id="cfgHoneypotTheater" min="3" max="30" value="${hp.theaterSeconds || 8}">
          </div>
          <div class="form-group">
            <label class="form-label">Exploración falsa mín (min)</label>
            <input type="number" class="form-input" id="cfgHpLiveMin" min="1" max="15" value="${hp.sandboxInteractiveMinMinutes || 1}">
          </div>
          <div class="form-group">
            <label class="form-label">Exploración falsa máx (min)</label>
            <input type="number" class="form-input" id="cfgHpLiveMax" min="1" max="15" value="${hp.sandboxInteractiveMaxMinutes || 5}">
          </div>
          <div class="form-group">
            <label class="form-label">Pantalla de bloqueo (seg)</label>
            <input type="number" class="form-input" id="cfgHpBreachSec" min="8" max="120" value="${hp.breachSeconds || 14}">
            <p class="form-hint" style="margin:4px 0 0;">En trampa real la secuencia de bloqueo es rápida (~8 s); este valor aplica a la vista admin lenta.</p>
          </div>
          <div class="form-group">
            <label class="form-label">Recolección mín (min)</label>
            <input type="number" class="form-input" id="cfgHoneypotHarvestMin" min="1" max="30" value="${hp.harvestMinMinutes || 1}">
          </div>
          <div class="form-group">
            <label class="form-label">Recolección máx (min)</label>
            <input type="number" class="form-input" id="cfgHoneypotHarvestMax" min="1" max="30" value="${hp.harvestMaxMinutes || 5}">
          </div>
          <div class="form-group">
            <label class="form-label">Bloqueo final (min)</label>
            <input type="number" class="form-input" id="cfgHoneypotLockMin" min="5" max="1440" value="${hp.lockMinutes || 45}">
          </div>
        </div>
        <div class="crozzo-toggle-stack">
          <label class="crozzo-toggle-row" title="Oculta cebos BACKDOOR, ROOT, SOPORTE, SUPERADMIN ficticio, etc.">
            <span class="user-toggle" aria-hidden="true">
              <input type="checkbox" id="cfgHoneypotProdStrict" ${hpProdStrict ? 'checked' : ''}>
              <span class="slider"></span>
            </span>
            <span class="crozzo-toggle-row__body">
              <span class="crozzo-toggle-row__title">Producción estricta (sin cebos de mantenimiento)</span>
              <span class="crozzo-toggle-row__hint">Recomendado en equipos en vivo. Se activa solo al cambiar la clave de fábrica KENNY. Sigue disponible el cebo <code>payaso</code> para pruebas.</span>
            </span>
          </label>
          <label class="crozzo-toggle-row" title="Acorta exploración falsa y recolección; también si hay 2ª trampa en 7 días con producción estricta">
            <span class="user-toggle" aria-hidden="true">
              <input type="checkbox" id="cfgHoneypotContencionRapida" ${hp.contencionRapida ? 'checked' : ''}>
              <span class="slider"></span>
            </span>
            <span class="crozzo-toggle-row__body">
              <span class="crozzo-toggle-row__title">Contención rápida (auditoría / reincidencia)</span>
              <span class="crozzo-toggle-row__hint">Escaneo de cebos: ≥4 usuarios señuelo distintos o ≥8 intentos en 10 min dispara trampa. Ver <code>docs/HONEYPOT-AUDITORIA.md</code>.</span>
            </span>
          </label>
          <label class="crozzo-toggle-row crozzo-toggle-row--danger" title="Borra Supabase y certificado del disco al disparar">
            <span class="user-toggle" aria-hidden="true">
              <input type="checkbox" id="cfgHoneypotWipe" ${hp.wipeSecrets ? 'checked' : ''}>
              <span class="slider"></span>
            </span>
            <span class="crozzo-toggle-row__body">
              <span class="crozzo-toggle-row__title">Modo extremo: borrar credenciales nube y .p12 del disco</span>
              <span class="crozzo-toggle-row__hint">No borra ventas ni productos; solo secretos. Úsalo solo si aceptas reconfigurar el equipo.</span>
            </span>
          </label>
        </div>
        <div class="btn-group" style="margin-top:12px;flex-wrap:wrap;gap:8px;">
          <button type="button" class="btn btn-primary" onclick="saveHoneypotSettings()">Guardar trampa</button>
          <button type="button" class="btn btn-outline" onclick="crozzoHpExportForensicReport()">⬇️ Informe forense JSON</button>
          ${hpLock.locked ? '<button type="button" class="btn btn-outline" onclick="crozzoClearHoneypotLock()">Liberar cuarentena (código legendario)</button>' : ''}
        </div>
      </div>
    </div>
    <div class="card" style="margin-top:14px;">
      <div class="card-header">
        <span class="card-title">🛡️ Política de contraseñas (local)</span>
      </div>
      <ul class="form-hint" style="margin:0;padding-left:18px;">
        <li>Mínimo 8 caracteres; prohibidas claves típicas (141414, 1234, …).</li>
        <li>Almacenamiento con <strong>PBKDF2</strong> (120 000 iteraciones); no se guardan en texto plano tras migrar.</li>
        <li>Tras 5 intentos fallidos, bloqueo 5 minutos en esta sesión de la app.</li>
        <li>El respaldo JSON <strong>no incluye</strong> contraseñas ni hashes.</li>
      </ul>
    </div>
    <div class="card" style="margin-top:14px;">
      <div class="card-header">
        <span class="card-title">🛡️ Menú Soporte y plataforma</span>
      </div>
      <p class="form-hint" style="margin:0 0 8px;">
        DIAN, certificado .p12, proveedor FE, modo demo/prod e identidad viven en <strong>Soporte y plataforma</strong>.
        Solo el rol <strong>Super Admin</strong> (cuenta de soporte interna o perfil nube equivalente) ve ese grupo.
      </p>
      <p class="form-hint" style="margin:0;">
        Rol <em>admin</em>: empresa, impuestos, comandas, facturas y <strong>Usuarios</strong> en Configuración — sin acceso a DIAN ni certificados.
      </p>
      <p class="form-hint" style="margin:10px 0 0;">
        Emparejar tablets con el sistema y modo pantallas (cocina, bar, fríos): botones en la <strong>pantalla de login</strong>.
      </p>
    </div>
    <div class="card" style="margin-top:14px;">
      <div class="card-header">
        <span class="card-title">💾 Respaldo local y portabilidad</span>
      </div>
      <p class="form-hint" style="margin:0 0 12px;">
        Exporta <code>pos_dian_config</code> y claves <code>crozzo_*</code> / <code>CROZZO_*</code> del navegador para copiar el POS a otro equipo o respaldar antes de un cambio mayor.
        La importación sobrescribe esas mismas claves; se recomienda exportar primero.
      </p>
      <div class="btn-group" style="gap:8px;flex-wrap:wrap;">
        <button type="button" class="btn btn-primary" onclick="crozzoExportLocalBackup()">📤 Exportar JSON</button>
        <label class="btn btn-outline" style="cursor:pointer;margin:0;">
          📥 Importar JSON
          <input type="file" accept="application/json,.json" style="display:none" onchange="crozzoImportLocalBackupFile(this)">
        </label>
      </div>
    </div>
  `;
}
function setRequireLogin(value) {
  if (!value) {
    showToast('El login al iniciar es obligatorio y no se puede desactivar.', 'warning');
    return;
  }
  const seg = config.get('seguridad') || {};
  config.set('seguridad', { ...seg, requiereLogin: true });
}
function setSessionIdleMinutes(value) {
  const n = Math.max(0, Math.min(480, parseInt(String(value), 10) || 0));
  const seg = config.get('seguridad') || {};
  config.set('seguridad', { ...seg, sessionIdleMinutes: n });
  config.addAudit('seguridad_idle', `Cierre por inactividad: ${n} min`);
  try {
    if (typeof crozzoInitSessionIdleWatch === 'function') crozzoInitSessionIdleWatch();
  } catch (_) {}
  showToast(n ? `Inactividad: cierre a los ${n} min` : 'Cierre por inactividad desactivado', 'info');
}
